  async function call(url,body,keepalive=false){const r=await fetch(url,{method:"POST",headers:headers(),body:JSON.stringify(body),keepalive});const d=await r.json().catch(()=>({}));if(!r.ok){const e=new Error(d.error||`http_${r.status}`);e.code=d.error||"request_failed";e.data=d;throw e}return d}
