  function intensity(c,s,initial=0,caption=""){const card=document.createElement("div");card.className="intensity-card";let start=Math.max(0,Math.min(10,Number(initial)||0));card.innerHTML=`<div class="intensity-head"><div><div class="symptom-name">${esc(s.name)}</div><div class="symptom-meta">${esc(caption)}</div></div><div class="intensity-number"><span>${start}</span>/10</div></div>`;const input=document.createElement("input");input.type="range";input.min="0";input.max="10";input.step="1";input.value=String(start);input.className="intensity-range";input.oninput=()=>card.querySelector("span").textContent=input.value;card.appendChild(input);c.appendChild(card);return()=>Number(input.value)}
