  async function flush(keepalive=false){if(!sessionId||!sessionToken||flushing)return;if(!eventQueue.length&&!snapshotQueue.length&&!usageMeasured.length&&!usagePost.length)return;flushing=true;const ev=eventQueue.splice(0,500),sn=snapshotQueue.splice(0,100),um=usageMeasured.splice(0,100),up=usagePost.splice(0,100);try{if(ev.length||sn.length)await call(OLD_API,{action:"batch",sessionId,sessionToken,events:ev,snapshots:sn},keepalive);if(um.length)await call(OLD_API,{action:"usage",sessionId,sessionToken,items:um},keepalive);if(up.length)await call(V5_API,{action:"post-usage",sessionId,sessionToken,items:up},keepalive)}catch(_){eventQueue.unshift(...ev);snapshotQueue.unshift(...sn);usageMeasured.unshift(...um);usagePost.unshift(...up)}finally{flushing=false;if(eventQueue.length||snapshotQueue.length||usageMeasured.length||usagePost.length)scheduleFlush(250)}}
  function scheduleFlush(ms=850){clearTimeout(flushTimer);flushTimer=setTimeout(()=>flush(false),ms)}function record(type,payload={}){if(!ready)return;eventQueue.push({tMs:Math.round(nowMs()),type,payload:{...payload,phase}});if(eventQueue.length>38)flush(false);else scheduleFlush()}
  function recordState(force=false,extra={}){if(!ready)return;const t=Math.round(nowMs()),state={...SetkaApp.getState(),requestKey,preState,preSymptoms,phase,plannedSeconds,...extra};eventQueue.push({tMs:t,type:"app_state",payload:state});if(force||t-lastSnapshot>=10000){snapshotQueue.push({tMs:t,state});lastSnapshot=t}persistActive();if(eventQueue.length>38)flush(false);else scheduleFlush()}
