  function closeUsage(){if(!currentUsage)return;currentUsage.endedMs=Math.round(nowMs());currentUsage.durationMs=Math.max(0,currentUsage.endedMs-currentUsage.startedMs);if(currentUsage.durationMs>=250)(currentUsage.phase==="after_feedback"?usagePost:usageMeasured).push({...currentUsage});currentUsage=null;scheduleFlush(200)}function markUsageSaved(id){if(currentUsage){currentUsage.saved=true;if(id)currentUsage.communityConfigId=id}}

