  function beginMeasured(startMs,deadline,target){phase="measured";ready=true;ending=false;newSessionRequired=false;sessionStartedWallMs=startMs;deadlineMs=deadline;measuredActiveMs=0;afterFeedbackActiveMs=0;lastInteraction=Date.now();lastActiveTick=Date.now();lastSnapshot=-Infinity;app.style.visibility="visible";layer.classList.add("hidden");hideNav();finishButton.textContent="✓";finishButton.setAttribute("aria-label","Завершить раньше");finishButton.classList.add("show");timerPill.classList.add("show");updateGameControls();record("session_start",{requestKey,preState,preSymptoms,plannedSeconds,appVersion:APP_VERSION});recordState(true);startTicker();loadCommunity();syncFavorites();if(target?.config){SetkaApp.openConfig(target.config,{type:"memory",id:target.id,communityId:null});record("memory_reopen",{noteId:target.id})}persistActive()}
  function startTicker(){clearInterval(ticker);ticker=setInterval(()=>{const now=Date.now(),dt=Math.max(0,now-lastActiveTick);lastActiveTick=now;if(!document.hidden&&now-lastInteraction<=30000){if(phase==="measured")measuredActiveMs+=dt;if(phase==="after_feedback")afterFeedbackActiveMs+=dt}if(phase==="measured"){const left=deadlineMs-now;timerPill.textContent=`${intentLabel(requestKey).toUpperCase()} · ${fmtClock(left)}`;if(left<=0&&!ending){if(noteOpen)pendingTimerEnd=true;else showPostSurvey("timer")}}else if(phase==="after_feedback"){timerPill.textContent=`СВОБОДНО · +${fmtClock(now-feedbackSubmittedMs)}`}if(ready&&nowMs()-lastSnapshot>=10000)recordState(true);persistActive()},250)}
  function updateGameControls(){const st=SetkaApp.getState();noteButton.classList.toggle("show",ready&&["measured","after_feedback"].includes(phase)&&st.view==="game");finishButton.classList.toggle("show",ready&&["measured","after_feedback"].includes(phase));timerPill.classList.toggle("show",ready&&["measured","after_feedback"].includes(phase))}
  async function loadCommunity(){try{const [c,r]=await Promise.all([old("community-list",{sessionId,sessionToken}),old("recommendations",{sessionId,sessionToken,requestKey})]);SetkaApp.setCommunity(c.items||[]);SetkaApp.setRecommendations({community:r.recommendedCommunity||[],patterns:r.recommendedPatterns||[]})}catch(_){}}
  async function syncFavorites(){for(const f of SetkaApp.getFavorites().slice(0,30)){if(f.communityId)continue;try{const d=await old("community-save",{sessionId,sessionToken,patternId:f.baseId||"tentacle-orbit",patternVersion:f.patternVersion||1,config:f.config,previewFrame:f.previewFrame,parentConfigId:f.parentCommunityId||null});SetkaApp.updateFavoriteMeta(f.id,{communityId:d.communityId})}catch(_){}}loadCommunity()}

  async function showPostSurvey(reason="timer",resume=false){if(ending||phase==="after_feedback")return;closeUsage();ending=true;completionReason=reason;phase="feedback";ready=true;finishButton.classList.remove("show");noteButton.classList.remove("show");timerPill.classList.remove("show");app.style.visibility="hidden";layer.classList.remove("hidden");hideNav();feedbackPromptedMs=resume&&feedbackPromptedMs?feedbackPromptedMs:Date.now();persistActive();if(!resume)try{await v5("feedback-prompt",{sessionId,sessionToken,at:new Date(feedbackPromptedMs).toISOString(),reason})}catch(_){}const b=baseBox(reason==="timer"?"Время сессии прошло":"Сессия остановлена","Сразу зафиксируем состояние — это отделяет измеряемый отрезок от свободного продолжения.","ОЦЕНКА ПОСЛЕ");const l=document.createElement("div");l.className="research-label";l.textContent="Как ты себя чувствуешь сейчас?";b.appendChild(l);const gf=faces(b);const h=document.createElement("div");h.className="research-label";h.textContent="Сессия помогла с запросом?";b.appendChild(h);const hw=document.createElement("div");hw.className="help-row";let helped=null;[[0,"Нет"],[1,"Немного"],[2,"Да"]].forEach(([v,t])=>{const x=document.createElement("button");x.type="button";x.className="help-button";x.textContent=t;x.onclick=()=>{helped=v;[...hw.children].forEach(y=>y.classList.remove("selected"));x.classList.add("selected")};hw.appendChild(x)});b.appendChild(hw);const active=symptoms.filter(s=>s.active&&Object.prototype.hasOwnProperty.call(preSymptoms,s.id)),sg=[];if(active.length){const sl=document.createElement("div");sl.className="research-label";sl.textContent="Интенсивность симптомов сейчас";b.appendChild(sl);active.forEach(s=>sg.push([s,intensity(b,s,preSymptoms[s.id],`до сессии ${preSymptoms[s.id]}/10`)]))}const btn=primary(b,"Сохранить оценку",async()=>{const postState=gf();if(!postState||helped===null){document.getElementById("researchError").textContent="Выбери состояние и оценку эффекта.";return}btn.disabled=true;const submitted=Date.now(),postSymptoms=Object.fromEntries(sg.map(([s,g])=>[s.id,g()]));try{if(sg.length)await ext("symptom-checkins",{sessionId,sessionToken,items:sg.map(([s,g])=>({symptomId:s.id,intensity:g(),phase:"post",observedAt:new Date(submitted).toISOString(),localOffsetMinutes:localOffset()}))});record("session_feedback",{preState,postState,helped,preSymptoms,postSymptoms});recordState(true,{postState,helped,postSymptoms});await flush(false);await old("finish-session",{sessionId,sessionToken,postState,helped,activeMs:Math.round(measuredActiveMs)});await v5("feedback-submit",{sessionId,sessionToken,at:new Date(submitted).toISOString(),measuredActiveMs:Math.round(measuredActiveMs)});feedbackSubmittedMs=submitted;phase="done_feedback";ready=false;ending=false;newSessionRequired=true;clearActive();showFeedbackResult(postState,helped,postSymptoms)}catch(_){btn.disabled=false;document.getElementById("researchError").textContent="Не удалось сохранить оценку."}})}
  function showFeedbackResult(postState,helped,postSymptoms){app.style.visibility="hidden";layer.classList.remove("hidden");hideNav();const b=baseBox("Измерение сохранено","Теперь можно уйти или продолжить исследовать. Всё после этой точки будет записано отдельно как добровольное продолжение.");const ok=document.createElement("div");ok.className="feedback-done";ok.textContent=face(postState);b.appendChild(ok);const p=document.createElement("div");p.className="research-copy";const d=Number(postState)-Number(preState);p.textContent=`Состояние ${d>0?"+":""}${d} · активное время ${fmtClock(measuredActiveMs)} · план ${Math.round(plannedSeconds/60)} мин`;b.appendChild(p);primary(b,"Продолжить исследовать",continueAfterFeedback);secondary(b,"Закончить",showCompletion)}
  async function continueAfterFeedback(){phase="after_feedback";ready=true;ending=false;newSessionRequired=true;afterFeedbackActiveMs=0;lastInteraction=Date.now();lastActiveTick=Date.now();app.style.visibility="visible";layer.classList.add("hidden");finishButton.textContent="×";finishButton.setAttribute("aria-label","Закончить продолжение");finishButton.classList.add("show");timerPill.classList.add("show");updateGameControls();try{await v5("continuation-start",{sessionId,sessionToken,at:new Date().toISOString()})}catch(_){}record("continuation_start",{});recordState(true);startTicker();if(SetkaApp.getState().view==="game")startUsage();persistActive()}
