  function openNoteComposer(){if(!ready||!["measured","after_feedback"].includes(phase))return;interaction();noteOpen=true;const snapshot=SetkaApp.getState(),elapsed=Math.round(nowMs()),notePhase=phase;app.style.visibility="hidden";layer.classList.remove("hidden");finishButton.classList.remove("show");noteButton.classList.remove("show");timerPill.classList.remove("show");const b=baseBox("Записать мысль","Конфигурация паттерна уже сохранена в контексте этой заметки.",notePhase==="after_feedback"?"СВОБОДНОЕ ПРОДОЛЖЕНИЕ":"ВО ВРЕМЯ СЕССИИ");const ta=document.createElement("textarea");ta.className="note-textarea";ta.placeholder="Что пришло сейчас?";b.appendChild(ta);const ctx=document.createElement("div");ctx.className="note-context";ctx.style.marginTop="10px";ctx.textContent=`${intentLabel(requestKey)} · ${fmtClock(elapsed)} · ${snapshot.patternId||"pattern"} · снимок конфигурации`;b.appendChild(ctx);const save=primary(b,"Сохранить заметку",async()=>{const text=ta.value.trim();if(!text){document.getElementById("researchError").textContent="Напиши хотя бы одну строку.";return}save.disabled=true;try{const d=await v5("note-create",{sessionId,sessionToken,text,phase:notePhase,observedAt:new Date().toISOString(),localOffsetMinutes:localOffset(),sessionElapsedMs:elapsed,requestKey,state:snapshot});record("note_create",{noteId:d.item?.id||null,elapsedMs:elapsed,patternId:snapshot.patternId||null});recordState(true,{noteId:d.item?.id||null});closeNoteComposer()}catch(_){save.disabled=false;document.getElementById("researchError").textContent="Не удалось сохранить."}});secondary(b,"Отмена",closeNoteComposer);setTimeout(()=>ta.focus(),60)}
