  async function showNotes(){app.style.visibility="hidden";layer.classList.remove("hidden");showNav("me");let items=[];try{items=(await v5("note-list",{sessionId,sessionToken,limit:500})).items||[]}catch(_){}const b=baseBox("Заметки","Каждая мысль хранит свой момент времени и точный снимок конфигурации.","ПАМЯТЬ");const list=document.createElement("div");list.className="notes-list";b.appendChild(list);if(!items.length)list.innerHTML='<div class="research-copy">Пока нет заметок. Во время паттерна нажми +.</div>';items.forEach(n=>{const card=document.createElement("button");card.type="button";card.className="note-card";card.innerHTML=`<div class="note-top"><strong>${fmtDate(n.observed_at)}</strong><span class="note-context">${n.phase==="after_feedback"?"после оценки":"сессия"}</span></div><div class="note-text">${esc(n.note_text)}</div><div class="note-context">${esc(intentLabel(n.request_key))} · ${fmtClock(n.session_elapsed_ms||0)} · ${esc(n.pattern_id||"без паттерна")}</div>${n.config&&Object.keys(n.config).length?'<div class="note-open">Открыть тот самый паттерн ↗</div>':''}`;card.onclick=()=>showNoteDetail(n);list.appendChild(card)})}
