  async function showSymptoms(){app.style.visibility="hidden";layer.classList.remove("hidden");showNav("symptoms");await refreshSymptoms();const b=baseBox("Симптомы","Отмечай интенсивность в любое время. Сессии автоматически связывают точки до и после.","ТРЕКЕР");const list=document.createElement("div");list.className="tracker-list";b.appendChild(list);const active=symptoms.filter(s=>s.active);if(!active.length)list.innerHTML='<div class="research-copy">Пока ничего не отслеживается.</div>';active.forEach(s=>{const x=document.createElement("button");x.type="button";x.className="symptom-row";x.innerHTML=`<div class="symptom-top"><span class="symptom-name">${esc(s.name)}</span><span class="symptom-value">${s.lastCheckin?`${s.lastCheckin.intensity}/10`:"—"}</span></div><div class="symptom-meta">${s.checkinCount||0} точек${s.lastCheckin?` · ${fmtDate(s.lastCheckin.observed_at)}`:""}</div>`;x.onclick=()=>showHistory(s,7);list.appendChild(x)});primary(b,"+ Добавить симптом",showAddSymptom);secondary(b,"Быстрая отметка",()=>showQuickCheckin(active))}
  function showAddSymptom(){showNav("symptoms");const b=baseBox("Что отслеживать?","Выбери вариант или добавь свой.","НОВЫЙ СИМПТОМ");const get=options(b,SYMPTOM_PRESETS);const btn=primary(b,"Добавить",async()=>{const key=get();if(!key)return;let name=SYMPTOM_PRESETS.find(x=>x[0]===key)?.[1]||"";if(key==="custom")name=prompt("Название симптома:","")?.trim()||"";if(!name)return;btn.disabled=true;try{const d=await ext("symptom-add",{sessionId,sessionToken,name,symptomKey:key==="custom"?null:key});await refreshSymptoms();showLogSymptom(d.item,true)}catch(_){btn.disabled=false}});secondary(b,"Назад",showSymptoms)}
  function showQuickCheckin(active){if(!active.length){showAddSymptom();return}showNav("symptoms");const b=baseBox("Как сейчас?","Новая точка попадёт на временную шкалу.","БЫСТРАЯ ОТМЕТКА");const gs=active.map(s=>[s,intensity(b,s,s.lastCheckin?.intensity??0,"0 — нет · 10 — максимум")]);const btn=primary(b,"Сохранить",async()=>{btn.disabled=true;try{await ext("symptom-checkins",{sessionId,sessionToken,items:gs.map(([s,g])=>({symptomId:s.id,intensity:g(),phase:"standalone",standalone:true,observedAt:new Date().toISOString(),localOffsetMinutes:localOffset()}))});showSymptoms()}catch(_){btn.disabled=false}});secondary(b,"Назад",showSymptoms)}
  function showLogSymptom(s,first=false){showNav("symptoms");const b=baseBox(s.name,first?"Сразу зафиксируем первую интенсивность.":"Новая точка на временной шкале.","ИНТЕНСИВНОСТЬ");const g=intensity(b,s,s.lastCheckin?.intensity??0,"0 — совсем нет · 10 — максимально сильно");const btn=primary(b,"Сохранить",async()=>{btn.disabled=true;try{await ext("symptom-checkins",{sessionId,sessionToken,items:[{symptomId:s.id,intensity:g(),phase:"standalone",standalone:true,observedAt:new Date().toISOString(),localOffsetMinutes:localOffset()}]});await refreshSymptoms();showHistory(symptoms.find(x=>x.id===s.id)||s,7)}catch(_){btn.disabled=false}});secondary(b,"Назад",showSymptoms)}
  async function showHistory(s,days=7){showNav("symptoms");let d={items:[],summary:{}};try{d=await ext("symptom-history",{sessionId,sessionToken,symptomId:s.id,days})}catch(_){}const b=baseBox(s.name,"Интенсивность во времени. Заполненная точка — перед сессией, серая — после.","ДИНАМИКА");b.insertAdjacentHTML("beforeend",historySvg(d.items||[]));const sm=d.summary||{},ks=document.createElement("div");ks.className="history-kpis";ks.innerHTML=mini(sm.count||0,"отметок")+mini(Number(sm.avgIntensity||0).toFixed(1),"средняя")+mini(sm.peak||0,"пик")+mini(`${Number(sm.avgSessionDrop||0)>=0?"↓":"↑"}${Math.abs(Number(sm.avgSessionDrop||0)).toFixed(1)}`,"после сессий");b.appendChild(ks);const rr=document.createElement("div");rr.className="range-row";[[1,"24ч"],[7,"7д"],[30,"30д"],[0,"всё"]].forEach(([v,l])=>{const x=document.createElement("button");x.type="button";x.className=`range-chip ${v===days?"active":""}`;x.textContent=l;x.onclick=()=>showHistory(s,v);rr.appendChild(x)});b.appendChild(rr);primary(b,"+ Новая отметка",()=>showLogSymptom(s));secondary(b,"Назад",showSymptoms)}
  function historySvg(items){if(!items.length)return'<div class="research-copy" style="margin-top:14px">Пока нет точек.</div>';const W=380,H=210,p=28,times=items.map(x=>Date.parse(x.observed_at)),min=Math.min(...times),max=Math.max(...times),span=Math.max(1,max-min);let grid="";for(let i=0;i<=5;i++){const y=p+(H-p*2)*i/5;grid+=`<line class="history-grid" x1="${p}" y1="${y}" x2="${W-p}" y2="${y}"/><text class="history-axis" x="6" y="${y+3}">${10-i*2}</text>`}const pts=items.map((x,i)=>{const xx=p+(W-p*2)*(Date.parse(x.observed_at)-min)/span,yy=p+(H-p*2)*(1-Number(x.intensity)/10);return{x,y:yy,row:x}}),poly=pts.map(q=>`${q.x},${q.y}`).join(" "),dots=pts.map(q=>`<circle class="history-dot ${q.row.phase||""}" cx="${q.x}" cy="${q.y}" r="4"><title>${fmtDate(q.row.observed_at)} · ${q.row.intensity}/10</title></circle>`).join("");return `<svg class="history-svg" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none">${grid}<polyline class="history-line" points="${poly}"/>${dots}</svg>`}

  async function showInvite(){showNav("me");let s={};try{s=(await ext("invite-stats",{sessionId,sessionToken})).stats||{}}catch(_){}const b=baseBox("Инвайты","Каждый ID хранит связь с тем, кто его создал.","СОЦИАЛЬНОЕ ДЕРЕВО");const ks=document.createElement("div");ks.className="invite-stats";ks.innerHTML=mini(s.created||0,"создано")+mini(s.activated||0,"активировано")+mini(s.repeaters||0,"вернулись")+mini(s.branches||0,"пригласили дальше");b.appendChild(ks);const btn=primary(b,"Создать новый ID",async()=>{btn.disabled=true;try{const d=await ext("invite-create",{sessionId,sessionToken});showInviteCode(d.invite.access_code)}catch(e){btn.disabled=false;document.getElementById("researchError").textContent=e.code==="invite_limit"?"Лимит инвайтов достигнут.":"Не удалось создать ID."}});secondary(b,"Назад",showMe)}
  function showInviteCode(code){showNav("me");const b=baseBox("ID готов","Отправь другу этот персональный ID.","ИНВАЙТ");const c=document.createElement("div");c.className="invite-code";c.textContent=code;b.appendChild(c);primary(b,"Скопировать",async()=>{try{await navigator.clipboard.writeText(code);document.getElementById("researchError").textContent="Скопировано"}catch(_){}});secondary(b,"Назад",showInvite)}

  async function handleSaved(fav,origin){interaction();markUsageSaved(fav.communityId||null);record("favorite_save",{origin,favoriteId:fav.id});recordState(true);try{const d=await old("community-save",{sessionId,sessionToken,patternId:fav.baseId||"tentacle-orbit",patternVersion:fav.patternVersion||1,config:fav.config,previewFrame:fav.previewFrame,parentConfigId:fav.parentCommunityId||null});SetkaApp.updateFavoriteMeta(fav.id,{communityId:d.communityId});markUsageSaved(d.communityId);loadCommunity()}catch(_){}}
  async function handleRemoved(fav,origin){interaction();record("favorite_remove",{origin,favoriteId:fav.id,communityId:fav.communityId||null});recordState(true);try{await old("community-unsave",{sessionId,sessionToken,communityId:fav.communityId||null,patternId:fav.baseId||"tentacle-orbit",patternVersion:fav.patternVersion||1,config:fav.config});loadCommunity()}catch(_){}}
  function listen(name,fn){window.addEventListener(`setka:${name}`,e=>{if(!ready)return;fn(e.detail||{})})}
  listen("pattern-open",d=>{interaction();startUsage(d.state);record("pattern_open",{sourceType:d.sourceType,sourceId:d.sourceId,communityId:d.communityId||null});recordState(true);updateGameControls()});listen("view",d=>{interaction();if(d.view==="library")closeUsage();else if(!currentUsage)startUsage(d.state);record("view_change",{view:d.view});recordState(true);updateGameControls()});listen("library-page",d=>{interaction();record("library_page",{page:d.page});recordState(true)});listen("gesture-start",d=>{interaction();record("gesture_start",{fingers:d.fingers,x:d.x,y:d.y});recordState(true,{gesture:{active:true,fingers:d.fingers,x:d.x,y:d.y}})});listen("gesture-move",d=>{interaction();const t=Date.now();if(t-lastMoveRecord<95)return;lastMoveRecord=t;recordState(false,{gesture:{active:true,fingers:d.fingers,x:d.x,y:d.y,dx:d.dx,dy:d.dy}})});listen("gesture-end",d=>{interaction();record("gesture_end",{fingers:d.fingers});recordState(true,{gesture:{active:false}})});listen("color",d=>{interaction();record("color_change",{from:d.from,to:d.to});recordState(true)});listen("instructions-open",()=>{interaction();record("instructions_open");recordState(true,{overlay:"instructions"})});listen("instructions-close",()=>{interaction();record("instructions_close");recordState(true,{overlay:null})});listen("favorite-saved",d=>handleSaved(d.favorite,d.origin));listen("favorite-removed",d=>handleRemoved(d.favorite,d.origin));
  finishButton.onclick=()=>{interaction();if(phase==="measured"&&!ending)showPostSurvey("early");else if(phase==="after_feedback")endContinuation()};noteButton.onclick=openNoteComposer;
  nav.addEventListener("click",e=>{const b=e.target.closest("button[data-page]");if(!b)return;const p=b.dataset.page;if(p==="today"){if(newSessionRequired)showCompletion();else showToday()}if(p==="patterns")showPatternsPortal();if(p==="symptoms")showSymptoms();if(p==="me")showMe()});
  window.addEventListener("resize",()=>{if(ready){interaction();record("viewport_change",{width:innerWidth,height:innerHeight,dpr:devicePixelRatio||1});recordState(true)}});document.addEventListener("visibilitychange",()=>{if(!ready)return;if(!document.hidden){interaction();lastActiveTick=Date.now();if(phase==="measured"&&Date.now()>=deadlineMs&&!ending&&!noteOpen)showPostSurvey("timer")}record(document.hidden?"app_hidden":"app_visible");if(document.hidden)flush(true)});window.addEventListener("pagehide",()=>{if(!ready)return;closeUsage();record("page_exit",{});recordState(true);flush(true);if(phase==="measured")call(OLD_API,{action:"end",sessionId,sessionToken},true).catch(()=>{});if(phase==="after_feedback")call(V5_API,{action:"continuation-end",sessionId,sessionToken,at:new Date().toISOString(),afterFeedbackActiveMs:Math.round(afterFeedbackActiveMs)},true).catch(()=>{})});setInterval(()=>{if(ready)flush(false)},5000);

  async function restoreActive(a){sessionId=a.sessionId;sessionToken=a.sessionToken;participant=a.participant;profile=a.profile;requestKey=a.requestKey;preState=a.preState;preSymptoms=a.preSymptoms||{};plannedSeconds=a.plannedSeconds||600;deadlineMs=a.deadlineMs||0;sessionStartedWallMs=a.sessionStartedWallMs||Date.now();phase=a.phase;measuredActiveMs=a.measuredActiveMs||0;afterFeedbackActiveMs=a.afterFeedbackActiveMs||0;feedbackPromptedMs=a.feedbackPromptedMs||0;feedbackSubmittedMs=a.feedbackSubmittedMs||0;completionReason=a.completionReason||"timer";try{await old("community-list",{sessionId,sessionToken});await refreshSymptoms()}catch(_){clearActive();return false}if(phase==="measured"){ready=true;ending=false;app.style.visibility="visible";layer.classList.add("hidden");hideNav();finishButton.textContent="✓";if(a.lastAppState?.view==="game"&&a.lastAppState?.config)SetkaApp.openConfig(a.lastAppState.config,{type:a.lastAppState.sourceType||"working",id:a.lastAppState.sourceId||"tentacle-orbit",communityId:a.lastAppState.communityId||null});updateGameControls();startTicker();loadCommunity();if(Date.now()>=deadlineMs)showPostSurvey("timer");return true}if(phase==="feedback"){ready=true;ending=false;showPostSurvey(completionReason,true);return true}if(phase==="after_feedback"){ready=true;newSessionRequired=true;app.style.visibility="visible";layer.classList.add("hidden");hideNav();finishButton.textContent="×";if(a.lastAppState?.view==="game"&&a.lastAppState?.config)SetkaApp.openConfig(a.lastAppState.config,{type:a.lastAppState.sourceType||"working",id:a.lastAppState.sourceId||"tentacle-orbit",communityId:a.lastAppState.communityId||null});updateGameControls();startTicker();loadCommunity();if(SetkaApp.getState().view==="game")startUsage();return true}return false}
  (async()=>{app.style.visibility="hidden";const saved=(()=>{try{return JSON.parse(localStorage.getItem(ACTIVE_KEY)||"null")}catch(_){return null}})();if(saved&&localStorage.getItem(ACCESS_KEY)){if(await restoreActive(saved))return}const code=localStorage.getItem(ACCESS_KEY);if(code){baseBox("Подключаем SETKA","Проверяем ID и этот браузер…");try{await claim(code)}catch(_){localStorage.removeItem(ACCESS_KEY);showGate()}}else showGate()})();
